import z3 as z, itertools as it, networkx as nx, time, json

def allowed(x,y,F,r):
    k=len(F)
    # F adjacency matrix
    return z.Or(z.And(x<r-1,y<r-1,x!=y),z.And(x<r-1,y>=r-1),z.And(y<r-1,x>=r-1),*[z.And(x==r-1+a,y==r-1+b) for a in range(k) for b in range(k) if F[a][b]])
def mat(G): return nx.to_numpy_array(G,dtype=int).tolist()
def synth(h,r,maxsec=60):
    start=time.time(); pairs=list(it.combinations(range(h),2)); E={ij:z.Bool('e%d_%d'%ij) for ij in pairs}
    edge=lambda a,b:E[tuple(sorted((a,b)))]
    s=z.Solver();s.set(timeout=10000)
    hosts=[nx.star_graph(3),nx.complete_graph(3),nx.path_graph(4),nx.cycle_graph(4)]
    for t,Fg in enumerate(hosts):
        F=mat(Fg);k=len(F); roles=[z.Int('role%d_%d'%(t,i)) for i in range(h)]
        s.add(*[z.And(x>=0,x<r-1+k) for x in roles])
        for i,j in pairs:
            s.add(z.Implies(roles[i]>=r-1,roles[i]!=roles[j]))
            s.add(z.Implies(edge(i,j),allowed(roles[i],roles[j],F,r)))
        if t==0:
            for i in range(4):s.add(roles[i]==r-1+i)
            for i in range(4,h):s.add(roles[i]<r-1)
    count=0
    while time.time()-start<maxsec:
        result=s.check()
        if result!=z.sat:return str(result),count,None
        m=s.model();G=nx.Graph();G.add_nodes_from(range(h));G.add_edges_from(ij for ij in pairs if z.is_true(m.eval(E[ij],model_completion=True)))
        o=z.Solver(); c=[z.Int('c%d'%i) for i in range(h)];o.add(*[z.And(x>=0,x<r) for x in c])
        for a,b in G.edges():o.add(z.Or(c[a]!=c[b],c[a]==r-1))
        for a in G:
            for ns in it.combinations(G[a],3):o.add(z.Or(*[c[v]!=r-1 for v in (a,)+ns]))
        for vs in it.combinations(range(h),3):
            if G.subgraph(vs).number_of_edges()==3:o.add(z.Or(*[c[v]!=r-1 for v in vs]))
        paths=set()
        for b,c0 in G.edges():
            for a in G[b]:
                for d in G[c0]:
                    if len({a,b,c0,d})==4:paths.add(tuple(sorted((a,b,c0,d))))
        for vs in paths:o.add(z.Or(*[c[v]!=r-1 for v in vs]))
        if o.check()==z.unsat:
            return 'FOUND',count,list(G.edges())
        om=o.model();cols=[om.eval(x).as_long() for x in c]
        I=[i for i in G if cols[i]==r-1]
        violations=[edge(a,b) for a,b in pairs if cols[a]==cols[b] and cols[a]!=r-1]
        for vs in it.combinations(I,3):violations.append(z.And(*[edge(a,b) for a,b in it.combinations(vs,2)]))
        for vs in it.combinations(I,4):
            for center in vs:violations.append(z.And(*[edge(center,b) for b in vs if b!=center]))
            for p in it.permutations(vs):
                if p[0]<p[-1]:violations.append(z.And(*[edge(p[j],p[j+1]) for j in range(3)]))
        s.add(z.Or(*violations));count+=1
    return 'TIME',count,None
for h in range(6,16):
    ans=synth(h,3,60)
    print(h,ans,flush=True)
    if ans[0]=='FOUND':
        json.dump({'h':h,'edges':ans[2]},open('foundH.json','w'));break

