from math import factorial as fac, comb
from functools import lru_cache
from fractions import Fraction
import mpmath as mp

def add(a,b):
 c=[0]*max(len(a),len(b))
 for i,x in enumerate(a):c[i]+=x
 for i,x in enumerate(b):c[i]+=x
 return c

def mul(a,b):
 c=[0]*(len(a)+len(b)-1)
 for i,x in enumerate(a):
  for j,y in enumerate(b):c[i+j]+=x*y
 return c

def star_poly(k):
 # 1 for omitted vertices, z for each selected path; two orientations of nontrivial paths
 p=[comb(k,j) for j in range(k+1)]
 for j in range(k-1):p[j+1]+=2*(k-1)*comb(k-2,j)
 for j in range(k-2):p[j+1]+=(k-1)*(k-2)*comb(k-3,j)
 return p

def path_poly(k):
 P=[[1]]
 for i in range(1,k+1):
  p=mul([1,1],P[-1])
  for j in range(i-1):p=add(p,[0]+[2*x for x in P[j]])
  P.append(p)
 return P[k]

@lru_cache(None)
def twice_h(b,c,d):
 # labeled proper undirected cyclic orders; a two-vertex cyclic order has weight 1/2
 total=0
 for t in range((b+c+d)%2,min(b,c,d)+1,2):
  a=(b+c-d-t)//2;bb=(b+d-c-t)//2;cc=(c+d-b-t)//2
  if min(a,bb,cc)<0:continue
  K=a+bb+cc+t
  if K==0:continue
  num=fac(b)*fac(c)*fac(d)*fac(K-1)*2**t
  den=fac(a)*fac(bb)*fac(cc)*fac(t)
  assert num%den==0
  total+=num//den
 return total

def twice_cycles(P,b,c):
 a=len(P)-1
 total=0
 for i,x in enumerate(P):
  for j in range(b+1):
   for k in range(c+1):total+=x*comb(b,j)*comb(c,k)*twice_h(i,j,k)
 total-=a*b+a*c+b*c
 assert total%2==0
 return total

for k in [4,5,6,7]:
 L=2
 for q in [k*4,k*8,k*12]:
  A=star_poly(L*k)
  for _ in range(q//k-L):A=mul(A,star_poly(k))
  B=path_poly((L-1)*k+1)
  for _ in range(q//k-L+1):B=mul(B,path_poly(k))
  ca=twice_cycles(A,q,q);cb=twice_cycles(B,q,q-1)
  n=3*q
  asym=3*(-1+Fraction(k-2,k)+Fraction((k-2)*(k-3),4*k))
  print('k,q',k,q,'nlog(B/A)',float(n*mp.log(mp.mpf(cb)/ca)),'limit',float(asym),flush=True)

